const float* nucVectors(int bitsPerCell, int rate15) {
    if (rate15 < 2 || rate15 > 13) return nullptr;
    int r = rate15 - 2;
    switch (bitsPerCell) {
    case 4: return kN16[r];
    case 6: return kN64[r];
    case 8: return kN256[r];
    case 10: return kN1024[r];
    case 12: return kN4096[r];
    default: return nullptr;
    }
}
const unsigned short* groupPermutation(int nInner, int bitsPerCell, int rate15) {
    for (const auto& e : kPermIndex)
        if (e.n == nInner && e.mod == bitsPerCell && e.rate == rate15) return kPerm + e.off;
    return nullptr;
}
